import{_ as a,C as n,o as e,c as d,a0 as r,b as s,w as i,a as c,E as l,a1 as p}from"./chunks/framework.DScjKhBS.js";const h=""+new URL("../report/agency-lifecycle-04-recommendations.png",import.meta.url).href,C=JSON.parse('{"title":"Prioritised Recommendations","description":"Ranked interventions by impact, effort, and readiness for an Elixirr Digital context.","frontmatter":{"title":"Prioritised Recommendations","description":"Ranked interventions by impact, effort, and readiness for an Elixirr Digital context."},"headers":[],"relativePath":"reports/agency-project-lifecycle/04-recommendations.md","filePath":"reports/agency-project-lifecycle/04-recommendations.md"}'),m={name:"reports/agency-project-lifecycle/04-recommendations.md"};function u(g,t,f,y,b,v){const o=n("Mermaid");return e(),d("div",null,[t[1]||(t[1]=r('<figure class="report-section-image-wrapper" aria-labelledby="fig-recommendations-caption"><img src="'+h+'" alt="Engineer&#39;s workbench with tools arranged by priority tier" loading="lazy" class="report-section-image"><figcaption id="fig-recommendations-caption">Engineer&#39;s workbench with tools arranged by priority tier</figcaption></figure><h1 id="_4-prioritised-recommendations" tabindex="-1">4. Prioritised Recommendations <a class="header-anchor" href="#_4-prioritised-recommendations" aria-label="Permalink to &quot;4. Prioritised Recommendations&quot;">​</a></h1><p>Interventions ranked by <strong>expected impact on margin, quality, and delivery speed</strong> — weighted for the Elixirr Digital context (WordPress/Laravel, consultancy model, existing tooling).</p><h2 id="priority-tiers" tabindex="-1">Priority Tiers <a class="header-anchor" href="#priority-tiers" aria-label="Permalink to &quot;Priority Tiers&quot;">​</a></h2><h3 id="tier-1-high-impact-ready-now-0–30-days" tabindex="-1">Tier 1: High Impact, Ready Now (0–30 days) <a class="header-anchor" href="#tier-1-high-impact-ready-now-0–30-days" aria-label="Permalink to &quot;Tier 1: High Impact, Ready Now (0–30 days)&quot;">​</a></h3><p>These require minimal new tooling. The constraint is process adoption, not technology.</p><table tabindex="0"><thead><tr><th>#</th><th>Intervention</th><th>Phase</th><th>Expected Impact</th><th>Effort</th></tr></thead><tbody><tr><td>1</td><td><strong>Adopt spec-driven development</strong> (Specify → Plan → Tasks) with LLM assistance</td><td>5. Technical Spec</td><td>Reduces build-phase rework by 30–50%; makes agent-assisted coding dramatically more effective</td><td>Medium — templates, rules, team training</td></tr><tr><td>2</td><td><strong>Build a content ingestion pipeline</strong> (source → LLM transform → dry-run → WP-CLI import)</td><td>7. Content Population</td><td>Reduces content population time by 60–80%; removes the most common launch blocker</td><td>Medium — scripts, templates, per-project config</td></tr><tr><td>3</td><td><strong>Auto-generate SEO metadata</strong> (titles, descriptions, alt text) from page content</td><td>7. Content Population</td><td>Saves 1–2 days per project; improves SEO baseline consistency</td><td>Low — prompt workflow + spot-check review</td></tr><tr><td>4</td><td><strong>Auto-generate CMS documentation</strong> from the content model</td><td>9. Training</td><td>Eliminates the most commonly skipped deliverable; reduces post-launch support load</td><td>Low — prompt workflow, template</td></tr><tr><td>5</td><td><strong>Integrate accessibility and performance checks into CI</strong> (axe-core, Lighthouse CI)</td><td>8. QA</td><td>Catches issues during build instead of QA; reduces late-stage bug cost</td><td>Low — CI config only</td></tr></tbody></table><h3 id="tier-2-high-impact-requires-setup-30–90-days" tabindex="-1">Tier 2: High Impact, Requires Setup (30–90 days) <a class="header-anchor" href="#tier-2-high-impact-requires-setup-30–90-days" aria-label="Permalink to &quot;Tier 2: High Impact, Requires Setup (30–90 days)&quot;">​</a></h3><p>These need some infrastructure, tooling, or process change before they deliver value.</p><table tabindex="0"><thead><tr><th>#</th><th>Intervention</th><th>Phase</th><th>Expected Impact</th><th>Effort</th></tr></thead><tbody><tr><td>6</td><td><strong>Estimation model from historical data</strong> (time-tracking → calibrated ranges)</td><td>1. Estimation</td><td>Improves margin accuracy; reduces under-scoping</td><td>Medium — requires clean time data and a model</td></tr><tr><td>7</td><td><strong>AI-assisted proposal/SOW drafting</strong> from structured scope inputs</td><td>1. Estimation</td><td>Reduces proposal turnaround from days to hours</td><td>Medium — templates, prompt workflows, review process</td></tr><tr><td>8</td><td><strong>Design-to-dev token pipeline</strong> (Figma → Tokens Studio → code)</td><td>4. Design → 6. Build</td><td>Reduces handoff loss; improves design-build consistency</td><td>Medium — tooling setup, design team adoption</td></tr><tr><td>9</td><td><strong>Visual regression testing</strong> (Percy/BackstopJS in CI)</td><td>8. QA</td><td>Catches unintended visual changes automatically</td><td>Medium — setup, baseline capture, CI integration</td></tr><tr><td>10</td><td><strong>Automated launch checklist</strong> (runnable script/CI job)</td><td>10. Launch</td><td>Eliminates checklist gaps; makes launch repeatable</td><td>Low–Medium — script the current manual checklist</td></tr></tbody></table><h3 id="tier-3-medium-impact-emerging-90-days-pilot" tabindex="-1">Tier 3: Medium Impact, Emerging (90+ days / pilot) <a class="header-anchor" href="#tier-3-medium-impact-emerging-90-days-pilot" aria-label="Permalink to &quot;Tier 3: Medium Impact, Emerging (90+ days / pilot)&quot;">​</a></h3><p>Worth exploring but not yet reliable enough or high-enough impact to prioritise.</p><table tabindex="0"><thead><tr><th>#</th><th>Intervention</th><th>Phase</th><th>Expected Impact</th><th>Effort</th></tr></thead><tbody><tr><td>11</td><td><strong>AI-generated wireframes/layouts</strong> from page intents</td><td>4. Design</td><td>Could reduce wireframing time; quality still requires heavy human refinement</td><td>Medium — tool evaluation, workflow design</td></tr><tr><td>12</td><td><strong>Content quality drift detection</strong> (post-launch automated audits)</td><td>11. Post-Launch</td><td>Catches governance failures early</td><td>Medium — monitoring setup, threshold definition</td></tr><tr><td>13</td><td><strong>Client self-service AI assistant</strong> (CMS help chatbot)</td><td>11. Post-Launch</td><td>Reduces support tickets; improves client autonomy</td><td>Medium–High — RAG setup, content model indexing</td></tr><tr><td>14</td><td><strong>Competitive scan automation</strong> (LLM + SEMrush/Ahrefs data)</td><td>2. Discovery</td><td>Speeds up discovery; directional quality only</td><td>Low — prompt workflow</td></tr></tbody></table><hr><h2 id="implementation-sequence" tabindex="-1">Implementation Sequence <a class="header-anchor" href="#implementation-sequence" aria-label="Permalink to &quot;Implementation Sequence&quot;">​</a></h2>',15)),(e(),s(p,null,{default:i(()=>[l(o,{id:"mermaid-339",class:"mermaid",graph:"gantt%0A%20%20%20%20title%20Recommended%20Implementation%20Sequence%0A%20%20%20%20dateFormat%20%20YYYY-MM-DD%0A%20%20%20%20axisFormat%20%20%25b%0A%0A%20%20%20%20section%20Tier%201%20(Now)%0A%20%20%20%20Spec-driven%20development%20adoption%20%20%20%20%20%20%20%3At1%2C%202026-05-15%2C%2030d%0A%20%20%20%20Content%20ingestion%20pipeline%20%20%20%20%20%20%20%20%20%20%20%20%20%3At2%2C%202026-05-15%2C%2021d%0A%20%20%20%20SEO%20metadata%20generation%20workflow%20%20%20%20%20%20%20%3At3%2C%202026-05-15%2C%207d%0A%20%20%20%20CMS%20doc%20generation%20workflow%20%20%20%20%20%20%20%20%20%20%20%20%3At4%2C%202026-05-20%2C%2010d%0A%20%20%20%20Accessibility%20%2B%20perf%20in%20CI%20%20%20%20%20%20%20%20%20%20%20%20%20%3At5%2C%202026-05-15%2C%207d%0A%0A%20%20%20%20section%20Tier%202%20(30%E2%80%9390%20days)%0A%20%20%20%20Estimation%20model%20%2B%20data%20collection%20%20%20%20%20%3At6%2C%202026-06-15%2C%2045d%0A%20%20%20%20Proposal%2FSOW%20drafting%20workflow%20%20%20%20%20%20%20%20%20%3At7%2C%202026-06-15%2C%2021d%0A%20%20%20%20Design%20token%20pipeline%20%20%20%20%20%20%20%20%20%20%20%20%20%20%20%20%20%20%3At8%2C%202026-07-01%2C%2030d%0A%20%20%20%20Visual%20regression%20testing%20%20%20%20%20%20%20%20%20%20%20%20%20%20%3At9%2C%202026-06-15%2C%2014d%0A%20%20%20%20Automated%20launch%20checklist%20%20%20%20%20%20%20%20%20%20%20%20%20%3At10%2C%202026-06-15%2C%207d%0A%0A%20%20%20%20section%20Tier%203%20(Pilot)%0A%20%20%20%20AI%20wireframing%20evaluation%20%20%20%20%20%20%20%20%20%20%20%20%20%20%3At11%2C%202026-08-01%2C%2030d%0A%20%20%20%20Content%20drift%20monitoring%20%20%20%20%20%20%20%20%20%20%20%20%20%20%20%3At12%2C%202026-08-01%2C%2021d%0A%20%20%20%20Client%20AI%20assistant%20(pilot)%20%20%20%20%20%20%20%20%20%20%20%20%3At13%2C%202026-09-01%2C%2045d%0A"})]),fallback:i(()=>[...t[0]||(t[0]=[c(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=r('<hr><h2 id="what-this-does-not-cover" tabindex="-1">What This Does NOT Cover <a class="header-anchor" href="#what-this-does-not-cover" aria-label="Permalink to &quot;What This Does NOT Cover&quot;">​</a></h2><ul><li><strong>Sales and lead generation.</strong> Pre-estimation commercial activity is outside the design-and-build project flow.</li><li><strong>Creative strategy and brand.</strong> Subjective creative decisions remain human-led; AI assists with execution, not strategy.</li><li><strong>Organisational change.</strong> Team structure, hiring, and career path changes needed to support new workflows are covered in the <a href="./reports/dark-factory/10-adopting-the-shift.html">Dark Factory report</a> (skills by level, role evolution).</li><li><strong>Governance and compliance.</strong> GDPR, data handling, and AI governance controls are covered in the <a href="./reports/ai-governance/">AI Governance</a> and <a href="./reports/ai-augmented-dev-pipeline/08-governance-and-controls.html">AI-Augmented Dev Pipeline</a> reports.</li></ul><hr><h2 id="measuring-success" tabindex="-1">Measuring Success <a class="header-anchor" href="#measuring-success" aria-label="Permalink to &quot;Measuring Success&quot;">​</a></h2><p>For each intervention, track:</p><table tabindex="0"><thead><tr><th>Metric</th><th>Baseline</th><th>Target</th></tr></thead><tbody><tr><td><strong>Estimation accuracy</strong></td><td>Actual hours / estimated hours per project</td><td>Within ±15%</td></tr><tr><td><strong>Content population time</strong></td><td>Hours per 100 pages (current manual rate)</td><td>60–80% reduction</td></tr><tr><td><strong>Build-phase rework</strong></td><td>% of build hours spent on rework/scope change</td><td>30–50% reduction</td></tr><tr><td><strong>QA bug density</strong></td><td>Bugs found in QA per project</td><td>Shift-left: more found in build, fewer in QA</td></tr><tr><td><strong>Launch delay frequency</strong></td><td>% of projects launching on scheduled date</td><td>Improve from baseline</td></tr><tr><td><strong>Post-launch support tickets</strong></td><td>Tickets per month in first 3 months</td><td>30% reduction (via documentation + governance)</td></tr><tr><td><strong>Proposal turnaround</strong></td><td>Days from brief to proposal delivery</td><td>50% reduction</td></tr></tbody></table><hr><h2 id="relationship-to-existing-reports" tabindex="-1">Relationship to Existing Reports <a class="header-anchor" href="#relationship-to-existing-reports" aria-label="Permalink to &quot;Relationship to Existing Reports&quot;">​</a></h2><p>This analysis sits above and across the existing reports, connecting them to the full project lifecycle:</p><table tabindex="0"><thead><tr><th>Existing Report</th><th>Lifecycle Phases Covered</th></tr></thead><tbody><tr><td><a href="./reports/dark-factory/">Dark Factory</a></td><td>5 (Spec), 6 (Build) — spec-driven development, agent implementation</td></tr><tr><td><a href="./reports/ai-augmented-dev-pipeline/">AI-Augmented Dev Pipeline</a></td><td>6 (Build), 8 (QA) — CI, PR review, refactoring, testing</td></tr><tr><td><a href="./reports/structured-prompt-driven/">SPDD</a></td><td>5 (Spec) — structured prompts as first-class artifacts</td></tr><tr><td><a href="./reports/pr-review-continuity/">PR Review Continuity</a></td><td>6 (Build) — review capacity under constraints</td></tr><tr><td><a href="./reports/ai-governance/">AI Governance</a></td><td>Cross-cutting — GDPR, data handling, controls</td></tr><tr><td><strong>This report</strong></td><td><strong>1–11 — full lifecycle from estimation to post-launch</strong></td></tr></tbody></table><p>The gap in existing research was the phases outside of build: estimation, discovery, content planning, content population, training, and post-launch governance. This report fills that gap.</p>',12))])}const w=a(m,[["render",u]]);export{C as __pageData,w as default};
